mapper.select:
SELECT call_id, session_id, user_message_id, assistant_message_id, user_id, username, dept_id, tenant_id, agent_code, tool_name, query_text, request_payload, result_summary, assistant_answer, source_chunks, top_score, confidence_level, no_answer, status, cost_millis, error_message, feedback, feedback_remark, create_time, update_time FROM ai_chat_tool_call
tool_name = 'search_knowledge'
AND (query_text LIKE CONCAT('%', #{keyword}, '%') OR result_summary LIKE CONCAT('%', #{keyword}, '%') OR assistant_answer LIKE CONCAT('%', #{keyword}, '%'))
AND no_answer = #{noAnswer}
AND feedback = #{feedback}
AND confidence_level = #{confidenceLevel}
ORDER BY create_time DESC, call_id DESC
